/** Authored translations belong to the page, not the UI dictionary. Remote/custom
 * pages without translations keep their own content and original language. */
export function localitzaPagina(page, language = 'ca', publicKey) {
 const registeredKey=clauDePaginaPublica(page);
 const key=registeredKey||clauDePaginaPublica(page,publicKey);
 const translated = page?.translations?.[language];
 const bodyLanguage=key&&translated&&!Object.hasOwn(translated,'html')?(page.contentLanguage||'ca'):language;
 const localized=translated ? { ...page, ...translated, contentLanguage: bodyLanguage } : page;
 const labels=key&&IDIOMES_TAXONOMIA.includes(language)&&(!registeredKey||!translated&&language!=='ca')?etiquetesDePaginaPublica(key,localized?.labels,language):localized?.labels;
 return localized&&labels!==localized.labels?{...localized,labels}:localized;
}

export function aplicaDossierR10(copy) {
 const originals = Object.fromEntries(['fedivers', 'fediversity', 'node-zero', 'versions', 'publicar_mapa'].map(k => [k, copy[k]]));
 for (const key of ['habitatge', 'treball', 'publicar_mapa', 'fedivers', 'fediversity', 'node-zero', 'versions']) {
  const translations = {};
  for (const [language, d] of Object.entries(dossier)) {
   let content;
   if (key === 'habitatge' || key === 'treball') content = ruralPage((key === 'habitatge' ? housing : jobs)[language]);
   else if (key === 'publicar_mapa') {
    const m = d.map;
    content = language === 'ca' ? {html:section('h3',m[1])+originals.publicar_mapa.html} : { title:m[0], subtitle:m[1], lead:m[2], labels:[], html:section('h3',m[1])+'\n      '+[3,5,7].map(i=>section('h5',m[i],m[i+1])).join('\n      ') };
   } else if (key === 'versions') {
    const entry = section('h3', `${d.date} · ${d.version}`, d.prod, d.db, d.bridge, d.kit, d.todo);
    // The old register is history in its original language; do not present it as translated.
    // P0-62 · La fita de l'App Store obri la pàgina, en la llengua de la pàgina.
    // Encàrrec R13+R14 · La crònica de les Onades R13 i R14 va davant de la fita de l'App Store.
    const fita = `${fitaR13R14(language)}${fitaAppStore(language)}`;
    content = language === 'ca' ? { html:`\n      ${fita}${entry}\n      ${originals.versions.html}` } : {
     title: ({es:'Versiones',en:'Versions',eu:'Bertsioak',gl:'Versións'})[language], subtitle:d.version, lead:d.lead,
     html:`\n      ${fita}${entry}<div lang="ca">${originals.versions.html}</div>`, labels:[]
    };
   } else {
    const title = d.titles[['fedivers','fediversity','node-zero'].indexOf(key)];
    content = { title, subtitle:d.subtitle, lead:d.lead, html: statusHtml(d, language), labels:[] };
    if (key === 'fediversity') content.html = section('h3', 'NLnet · NGI Fediversity', `<a href="https://nlnet.nl/fediversity/" target="_blank" rel="noopener noreferrer"><img class="page-title-logo" src="/assets/uploads/ngi-fediversity-tag.svg" alt="NGI Fediversity" width="2040" height="503" /></a>`, d.grant)+content.html;
    // The detailed Valencian dossier remains readable after its dated update.
    if (language === 'ca') content = { lead:key === 'fediversity' ? originals[key].lead : d.lead, html:statusHtml(d, language)+ (key==='fediversity'?section('h3','Candidatura NLnet · estat de la sol·licitud',d.grant):'') + actualitzaDossierAnterior(originals[key].html) };
   }
   translations[language] = content;
  }
  Object.assign(copy[key], translations.ca, { translations, contentLanguage:'ca' });
 }
 if (copy.anima) {
  copy.anima.translations = {
   ca: { lead: "La IAIA utilitza l'imaginari de poble per a explicar la tecnologia. Este manifest presenta el seu paper narratiu, la manera de treballar i les reflexions que han acompanyat el projecte." },
   es: { lead: "La IAIA utiliza el imaginario de pueblo para explicar la tecnología. Este manifiesto presenta su papel narrativo, la manera de trabajar y las reflexiones que han acompañado el proyecto." },
   en: { lead: "IAIA uses the village imaginary to explain technology. This manifesto presents her narrative role, way of working, and the reflections that have accompanied the project." },
   eu: { lead: "IAIAk herriko iruditeria erabiltzen du teknologia azaltzeko. Manifestu honek bere zeregin narratiboa, lan egiteko modua eta proiektuari lagundu dioten gogoetak aurkezten ditu." },
   gl: { lead: "A IAIA utiliza o imaxinario de vila para explicar a tecnoloxía. Este manifesto presenta o seu papel narrativo, o xeito de traballar e as reflexións que acompañaron o proxecto." }
  };
 }
 aplicaClassificacioPaginesPubliques(copy);
}

function actualitzaDossierAnterior(html) {
 const paragraphs = html.replace(/<(p|li)>(.*?)<\/\1>/g, (whole, tag, body) => {
  const text = body.replace(/<[^>]+>/g, '');
  if (text.startsWith('Posar en servei el pilot independent del Node 0 amb base de dades pròpia')) {
   return `<${tag}>La <strong>base PostgreSQL 17.11 i l’API pròpia</strong> ja funcionen al Node 0. Falta <strong>connectar-hi la SPA</strong>, activar comptes i escriptures amb permisos comprovats i mesurar la càrrega real del servei i el consum elèctric. La mida de tota la màquina no és el mínim necessari per a un poble.</${tag}>`;
  }
  return whole;
 });
 return paragraphs
 .replace(/sense garantia de disponibilitat ni base de dades (?:independent|pròpia) encara\.?/g, 'sense garantia de disponibilitat; PostgreSQL propi ja està instal·lat, mentre la SPA continua amb Supabase.')
 .replace(/no té garantia de disponibilitat i que <strong>encara no acredita<\/strong> una base de dades independent fora del Supabase compartit/g, 'no té garantia de disponibilitat; <strong>ja té PostgreSQL propi</strong> per a l’API, amb la SPA encara connectada a Supabase')
 .replace(/Hui hi ha <strong>un sol servidor<\/strong> de dades, el <strong>Supabase<\/strong> de Sóc de Poble\./g, 'La SPA usa el <strong>Supabase</strong> de Sóc de Poble; l’API pròpia del Node 0 ja té <strong>PostgreSQL 17.11</strong>, encara sense comptes ni escriptures de persones activats.')
 .replace(/Hui continuen al <strong>Supabase de Sóc de Poble<\/strong>, mentre el <strong>pilot independent<\/strong> es prepara i es verifica\./g, 'La SPA continua amb <strong>Supabase</strong>. En paral·lel, l’<strong>API pròpia del Node 0</strong> ja persistix documents en PostgreSQL; encara cal activar-ne l’ús complet per les pantalles.')
 /* R10 · B4 (VFT-08) · L'original porta negretes: la regex les tolera i el reemplaçament les conserva. */
 .replace(/la (?:<strong>)?base de dades pròpia(?:<\/strong>)?, els dominis i la (?:<strong>)?interoperabilitat remota(?:<\/strong>)? continuen sent (?:<strong>)?condicions a demostrar(?:<\/strong>)?/g, 'la <strong>connexió de la SPA a la base pròpia</strong> i la <strong>interoperabilitat remota</strong> continuen sent <strong>condicions a demostrar</strong>')
 /* R10 · B4 (VFT-03) · Lectura REST del 6-11-2026: admin_llista_pobles() i admin_llegix_personalitzacio(uuid)
    existixen a producció (401 42501 a anon). L'agenda viva ja no pot dir que la 2611031700 no s'ha aplicat. */
 .replace(/, però les noves RPC de <code>2611031700_administracio_multipoble\.sql<\/code> encara no s’han aplicat a producció\./g, ', i la lectura REST del 6 de novembre troba a producció les noves RPC de <code>2611031700_administracio_multipoble.sql</code>.')
 /* R10 · B4 segona ronda (B4V-T2) · FEDI-04 i FEDI23 són la 2611031700 i la 2611032100: la mateixa lectura en troba
    les RPC. Ni la fita ni l'apartat «Pendent» poden dir que estan sense aplicar. */
 .replace(/Migracions SQL preparades, sense aplicar a producció\./g, 'Les dues migracions SQL (2611031700 i 2611032100) ja són a producció: la lectura REST del 6 de novembre en troba les RPC.')
 .replace(/Aplicar i provar al servidor de producció les <strong>RPC multipoble<\/strong> abans de declarar/g, 'Provar al servidor de producció les <strong>RPC multipoble</strong> (la lectura REST del 6 de novembre ja les hi troba) abans de declarar')
 .replace(/ja funciona en proves, però falta activar-lo al servidor central amb doble clau de seguretat\./g, 'ja funciona en proves, i el servidor central ja en té les peces, darrere d’una doble clau de seguretat.')
 .replace(/mentre continua <strong>en evolució<\/strong> cap a un <strong>node independent<\/strong> amb base de dades pròpia darrere del <strong>port neutral<\/strong>/g, 'ja disposa d’<strong>API amb PostgreSQL propi</strong> i continua <strong>en evolució</strong> cap a l’ús independent des de tota la SPA darrere del <strong>port neutral</strong>');
}
